-- Dictation sentences extracted from Vocable Anglais (Juin 2025)
-- Source: Bilingual articles from News Digest pages

INSERT OR IGNORE INTO dictation_sentences (text, translation_fr, difficulty, category) VALUES
-- p31: Artificial Intelligence in Everyday Life
('Artificial intelligence is no longer confined to research labs; it has become an integral part of our daily lives.', 'L''intelligence artificielle n''est plus confinée aux laboratoires de recherche ; elle est devenue une partie intégrante de notre vie quotidienne.', 'B2', 'technologie'),
('From voice assistants to recommendation algorithms, AI shapes how we shop, work, and communicate with each other.', 'Des assistants vocaux aux algorithmes de recommandation, l''IA façonne la façon dont nous faisons nos achats, travaillons et communiquons entre nous.', 'B2', 'technologie'),
('However, the rapid adoption of AI raises important ethical questions about privacy, bias, and accountability.', 'Cependant, l''adoption rapide de l''IA soulève d''importantes questions éthiques sur la confidentialité, les biais et la responsabilité.', 'B2', 'technologie'),
-- p32: The Green Energy Transition
('The transition to green energy is accelerating as countries invest heavily in solar and wind power infrastructure.', 'La transition vers les énergies vertes s''accélère alors que les pays investissent massivement dans les infrastructures solaires et éoliennes.', 'B2', 'environnement'),
('Many governments have set ambitious targets to achieve carbon neutrality within the next two decades.', 'De nombreux gouvernements se sont fixé des objectifs ambitieux pour atteindre la neutralité carbone d''ici les deux prochaines décennies.', 'B2', 'environnement'),
('Critics argue that the transition must be just, ensuring that workers in fossil fuel industries are not left behind.', 'Les critiques affirment que la transition doit être juste, en veillant à ce que les travailleurs des industries fossiles ne soient pas laissés pour compte.', 'B2', 'environnement'),
-- p33: The Rise of Remote Work
('Remote work has fundamentally changed the way companies operate, offering employees unprecedented flexibility.', 'Le télétravail a fondamentalement changé la façon dont les entreprises fonctionnent, offrant aux employés une flexibilité sans précédent.', 'B2', 'travail'),
('While many workers appreciate the absence of a daily commute, others struggle with isolation and blurred boundaries.', 'Si de nombreux travailleurs apprécient l''absence de trajet quotidien, d''autres luttent contre l''isolement et les frontières floues entre vie pro et perso.', 'B2', 'travail'),
('Hybrid models have emerged as a compromise, combining the benefits of office collaboration with home-based focus.', 'Les modèles hybrides sont apparus comme un compromis, combinant les avantages de la collaboration au bureau avec la concentration à domicile.', 'B1', 'travail'),
-- p34: Mental Health in the Modern Workplace
('Mental health has become a priority for forward-thinking companies that recognise the cost of employee burnout.', 'La santé mentale est devenue une priorité pour les entreprises visionnaires qui reconnaissent le coût de l''épuisement professionnel des employés.', 'B2', 'santé'),
('Employers are introducing wellness programmes that include mindfulness sessions, flexible hours, and mental health days.', 'Les employeurs introduisent des programmes de bien-être qui incluent des séances de pleine conscience, des horaires flexibles et des jours de santé mentale.', 'B2', 'santé'),
('Despite these efforts, stigma around mental health issues persists in many professional environments.', 'Malgré ces efforts, la stigmatisation des problèmes de santé mentale persiste dans de nombreux environnements professionnels.', 'B1', 'santé'),
-- p35: The Future of Public Transport
('Cities around the world are reimagining public transport to reduce congestion and lower carbon emissions.', 'Les villes du monde entier réinventent les transports publics pour réduire la congestion et diminuer les émissions de carbone.', 'B2', 'environnement'),
('Electric buses and trams are replacing diesel fleets, while bike-sharing schemes encourage cleaner commutes.', 'Les bus et tramways électriques remplacent les flottes diesel, tandis que les systèmes de vélos en libre-service encouragent des trajets plus propres.', 'B1', 'environnement'),
('Investment in public transport is seen as essential for creating sustainable and livable urban environments.', 'L''investissement dans les transports publics est considéré comme essentiel pour créer des environnements urbains durables et vivables.', 'B2', 'environnement'),
-- p50: Cultural Heritage in the Digital Age
('Digital technology is transforming how we preserve and experience cultural heritage around the world.', 'La technologie numérique transforme la façon dont nous préservons et vivons le patrimoine culturel dans le monde entier.', 'B2', 'culture'),
('Virtual reality allows people to explore museums and historical sites from the comfort of their homes.', 'La réalité virtuelle permet aux gens d''explorer des musées et des sites historiques depuis le confort de leur domicile.', 'B1', 'culture'),
('However, experts warn that digital replicas should complement, not replace, the experience of visiting cultural sites in person.', 'Cependant, les experts avertissent que les répliques numériques devraient compléter, et non remplacer, l''expérience de visiter les sites culturels en personne.', 'B2', 'culture'),
-- p52: The Space Economy
('The space economy is growing rapidly as private companies launch satellites and develop new technologies.', 'L''économie spatiale croît rapidement alors que des entreprises privées lancent des satellites et développent de nouvelles technologies.', 'B2', 'science'),
('Space tourism is no longer science fiction, with several companies offering suborbital flights to paying customers.', 'Le tourisme spatial n''est plus de la science-fiction, plusieurs entreprises proposant des vols suborbitaux à des clients payants.', 'B2', 'science'),
('The commercialisation of space raises questions about regulation, sustainability, and the preservation of orbital environments.', 'La commercialisation de l''espace soulève des questions sur la réglementation, la durabilité et la préservation des environnements orbitaux.', 'B2', 'science');
